use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let arr = input.as_array().unwrap();
    let mut result = Vec::new();
    let mut map = std::collections::HashMap::new();

    for item in arr {
        let key = item[0].as_i64().unwrap();
        let value = item[1].as_i64().unwrap();
        *map.entry(key).or_insert(0) += value;
    }

    for (key, &value) in map.iter() {
        result.push(Value::from(vec![Value::from(key), Value::from(value)]));
    }

    Value::from(result)
}
